insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_face_to_face','face-to-face','adjective','in the same place as the other person, so you can see each other directly','[{"senseId":"face_to_face_1","meaning":"in the same place as the other person, so you can see each other directly","acceptedParaphrases":["in person","meeting directly"],"masteryContexts":[{"contextId":"u9_31_face_to_face_meaning","text":"After months of video calls, the team finally had a face-to-face meeting in London.","meaning":"in the same place, seeing each other directly","wrongMeanings":["by email, without meeting","over the phone, without seeing","online, with cameras off"]},{"contextId":"u9_31_face_to_face_paraphrase","text":"In face-to-face lessons, teachers can notice when a student looks confused.","meaning":"happening in person, not online","wrongMeanings":["happening online with no camera","happening at home alone","happening through written messages"]}],"situationDistractors":["Two friends chatted on a video call from different countries.","A girl wrote a letter to her pen friend in Australia.","A boy left an anonymous comment on a website.","A boy sent his friend a voice message.","A girl emailed her teacher a question about homework.","Two cousins chatted on a video call across the world."],"gapDistractors":[{"contextId":"u9_31_face_to_face_gap_1","answer":"face-to-face","wrong":["tech-savvy","banned","underlying"]},{"contextId":"u9_31_face_to_face_gap_2","answer":"face-to-face","wrong":["tech-savvy","banned","underlying"]},{"contextId":"u9_31_face_to_face_gap_3","answer":"face-to-face","wrong":["tech-savvy","underlying","constructive"]}],"spellingErrors":["face-to-fase","face-too-face","fase-to-face","face-to-fce","face-ta-face","face-to-faice"],"masteryPassages":[{"passageId":"u9_31_face_to_face_passage_1","contextId":"u9_31_face_to_face_gap_1","text":"After months of chatting online, the two pen friends finally met ____ at the airport. They hugged and laughed for minutes.","answer":"face-to-face"},{"passageId":"u9_31_face_to_face_passage_2","contextId":"u9_31_face_to_face_gap_2","text":"Some problems are too serious to discuss by message. A ____ conversation lets you see how the other person is feeling.","answer":"face-to-face"}],"contextDependentParaphrases":[],"wrongParaphrases":["by phone","by letter","anonymously"],"misleadingDistractors":["by phone or online","by sending a letter","without being seen"],"teacherNote":"Adjective or adverb (hyphenated before a noun): in the same place as the other person (face-to-face meetings, talk face to face). Opposite here: virtual / online / remote. It is a fixed expression, so Word Families is not counted."}]'::jsonb,'[]'::jsonb,'["a face-to-face meeting","face-to-face contact","talk face to face"]'::jsonb,'live'),
('vocab_conference','conference','noun','a large formal meeting where people discuss a subject, often over several days','[{"senseId":"conference_1","meaning":"a large formal meeting where people discuss a subject, often over several days","acceptedParaphrases":["large formal meeting","organised event for discussion"],"masteryContexts":[{"contextId":"u9_32_conference_meaning","text":"The doctor flew to Tokyo to give a talk at an international medical conference.","meaning":"a large formal meeting on a subject","wrongMeanings":["a short private chat","a written report on a subject","a quiet place for studying"]},{"contextId":"u9_32_conference_paraphrase","text":"The company holds a video conference every Monday with offices in five countries.","meaning":"an organised meeting held online","wrongMeanings":["a recorded film shown online","a single phone call between two people","a written newsletter sent to staff"]}],"situationDistractors":["Two friends had a quick chat at the bus stop.","A secretary typed up the notes from yesterday’s meeting.","Students worked silently in the school library.","A boy whispered a joke to his friend in class.","A girl wrote a short note to her brother.","A student read quietly in the corner of the library."],"gapDistractors":[{"contextId":"u9_32_conference_gap_1","answer":"conference","wrong":["frustration","accuracy","perception"]},{"contextId":"u9_32_conference_gap_2","answer":"conference","wrong":["frustration","accuracy","perception"]},{"contextId":"u9_32_conference_gap_3","answer":"conference","wrong":["frustration","accuracy","perception"]}],"spellingErrors":["conferance","confrence","conferense","confference","conferece","conferrence"],"masteryPassages":[{"passageId":"u9_32_conference_passage_1","contextId":"u9_32_conference_gap_1","text":"Over three days, two thousand doctors met in Singapore to share new research. The ____ ended with a talk by a famous surgeon.","answer":"conference"},{"passageId":"u9_32_conference_passage_2","contextId":"u9_32_conference_gap_2","text":"Journalists had many questions about the new law. The minister answered them at a press ____ on Monday morning.","answer":"conference"}],"contextDependentParaphrases":[],"wrongParaphrases":["private chat","written report","quiet study room"],"misleadingDistractors":["a short private chat between two friends","a written report about a meeting","a room where students study quietly"],"teacherNote":"Noun (countable): a large formal meeting, often lasting several days, where people discuss a subject (attend a conference, a conference on ..., a video conference, a press conference). Boundary: a conference is bigger and more formal than a meeting. Word Families is not counted (confer is formal and rare at this level)."}]'::jsonb,'[]'::jsonb,'["attend a conference","a press conference","a video conference"]'::jsonb,'live'),
('vocab_suitable','suitable','adjective','right or acceptable for a particular person, purpose or situation','[{"senseId":"suitable_1","meaning":"right or acceptable for a particular person, purpose or situation","acceptedParaphrases":["right for","appropriate"],"masteryContexts":[{"contextId":"u9_33_suitable_meaning","text":"The hall is not suitable for a large conference because it only has fifty seats.","meaning":"right for a particular purpose","wrongMeanings":["too expensive for a particular purpose","famous for a particular purpose","dangerous for a particular purpose"]},{"contextId":"u9_33_suitable_paraphrase","text":"Can you suggest a suitable time for the video call next week?","meaning":"convenient and acceptable","wrongMeanings":["very early and inconvenient","already fully booked","long and boring"]}],"situationDistractors":["A girl could not understand the long instructions for her new camera.","A family decided the laptop was too expensive for them.","A boy threw away his old phone because the screen was broken.","A girl could not open the box because it was sealed too tightly.","A boy decided the trainers were too expensive.","A family threw away a broken chair."],"gapDistractors":[{"contextId":"u9_33_suitable_gap_1","answer":"suitable","wrong":["tech-savvy","underlying","non-verbal"]},{"contextId":"u9_33_suitable_gap_2","answer":"suitable","wrong":["tech-savvy","underlying","non-verbal"]},{"contextId":"u9_33_suitable_gap_3","answer":"suitable","wrong":["tech-savvy","underlying","banned"]}],"spellingErrors":["suteable","suitible","sutable","suitabel","suiteble","suitbale"],"wordFamilyForms":[{"form":"suitable","partOfSpeech":"adjective","example":"This film is not suitable for young children.","pedagogicallyUseful":true},{"form":"unsuitable","partOfSpeech":"adjective","example":"The hall was unsuitable for a large concert.","pedagogicallyUseful":true,"altExample":"The website was blocked because it was unsuitable for students."},{"form":"suit","partOfSpeech":"verb","example":"A quiet office would suit her better than a busy shop.","pedagogicallyUseful":true,"altExample":"Online lessons suit students who live far from school."}],"masteryPassages":[{"passageId":"u9_33_suitable_passage_1","contextId":"u9_33_suitable_gap_1","text":"The hall only holds thirty people. It is not ____ for a concert with three hundred guests.","answer":"suitable"},{"passageId":"u9_33_suitable_passage_2","contextId":"u9_33_suitable_gap_2","text":"The film contains a lot of violence. It is not ____ for young children.","answer":"suitable"}],"contextDependentParaphrases":[],"wrongParaphrases":["confusing","expensive","broken"],"misleadingDistractors":["very difficult to understand","too expensive to buy","old and broken"],"teacherNote":"Adjective: right or acceptable for a person, purpose or situation (suitable for, a suitable time/place/word). Boundary: suitable and appropriate are close synonyms; \"suitable for children\" is very common, while \"appropriate\" is often used about behaviour and language. The opposite unsuitable and the noun suitability are taught in the Word Family pathway."}]'::jsonb,'["unsuitable","suit"]'::jsonb,'["suitable for","a suitable time","not suitable for children"]'::jsonb,'live'),
('vocab_underlying_meaning','underlying meaning','noun','the real message of something, which is not stated directly but is suggested','[{"senseId":"underlying_meaning_1","meaning":"the real message of something, which is not stated directly but is suggested","acceptedParaphrases":["hidden message","real meaning below the surface"],"masteryContexts":[{"contextId":"u9_34_underlying_meaning_meaning","text":"On the surface the advert is about a car, but its underlying meaning is that success makes you happy.","meaning":"the message suggested but not said directly","wrongMeanings":["the message printed in large letters","the meaning given in a dictionary","the name of the company"]},{"contextId":"u9_34_underlying_meaning_paraphrase","text":"When a friend says \"I’m fine\" in a flat voice, the underlying meaning may be the opposite.","meaning":"the real message behind the words","wrongMeanings":["the exact words a person uses","the tone of voice a person uses","the language a person speaks"]}],"situationDistractors":["A student looked up the definition of \"obscure\" in a dictionary.","A girl read only the headline of a newspaper article.","A tourist used an app to translate a menu into English.","A student copied a definition from a dictionary.","A girl translated a short story into French.","A boy read the title of a book aloud."],"gapDistractors":[{"contextId":"u9_34_underlying_meaning_gap_1","answer":"underlying meaning","wrong":["direct object","reporting verb","digital native"]},{"contextId":"u9_34_underlying_meaning_gap_2","answer":"underlying meaning","wrong":["direct object","digital native","reporting verb"]},{"contextId":"u9_34_underlying_meaning_gap_3","answer":"underlying meaning","wrong":["direct object","digital native","reporting verb"]}],"spellingErrors":["underlaying meaning","underlying meening","underliing meaning","underlying meanning","underlyng meaning","underlying meanig"],"masteryPassages":[{"passageId":"u9_34_underlying_meaning_passage_1","contextId":"u9_34_underlying_meaning_gap_1","text":"On the surface, the poem describes a tree in winter. Its ____ is about growing old and losing friends.","answer":"underlying meaning"},{"passageId":"u9_34_underlying_meaning_passage_2","contextId":"u9_34_underlying_meaning_gap_2","text":"My friend said that I could do what I wanted. From her tone, I understood that the ____ was that she was upset.","answer":"underlying meaning"}],"contextDependentParaphrases":[],"wrongParaphrases":["dictionary definition","printed title","word-for-word translation"],"misleadingDistractors":["the dictionary definition of a single word","the title printed at the top of a text","a translation into another language"],"teacherNote":"Noun phrase: the real message that is suggested rather than stated (the underlying meaning of a text/comment/remark). Important for Paper 1 inference questions about what a writer implies. Boundary: the literal meaning is what the words say; the underlying meaning is what the writer suggests. Fixed phrase, so Word Families is not counted."}]'::jsonb,'[]'::jsonb,'["the underlying meaning of a text","find the underlying meaning","explain the underlying meaning"]'::jsonb,'live'),
('vocab_informal_language','informal language','noun','relaxed everyday words and expressions used with friends and family rather than in official situations','[{"senseId":"informal_language_1","meaning":"relaxed everyday words and expressions used with friends and family rather than in official situations","acceptedParaphrases":["everyday language","casual words and expressions"],"masteryContexts":[{"contextId":"u9_35_informal_language_meaning","text":"Contractions like \"don’t\" and phrasal verbs like \"get on with\" are features of informal language.","meaning":"everyday expressions used in relaxed situations","wrongMeanings":["official words used in legal documents","technical words used in science","foreign words borrowed from other languages"]},{"contextId":"u9_35_informal_language_paraphrase","text":"The examiner marked her report down because it was full of informal language.","meaning":"casual words not suitable for official writing","wrongMeanings":["very formal words not suitable for friends","difficult words used by experts","old words no longer used"]}],"situationDistractors":["A lawyer used complex legal terms in a contract.","A scientist wrote a report full of technical vocabulary.","A historian studied an ancient language that nobody speaks today.","A lawyer wrote a contract full of legal terms.","A scientist used technical words in a research paper.","A historian studied a language that nobody speaks today."],"gapDistractors":[{"contextId":"u9_35_informal_language_gap_1","answer":"informal language","wrong":["direct object","digital native","reporting verb"]},{"contextId":"u9_35_informal_language_gap_2","answer":"informal language","wrong":["direct object","digital native","reporting verb"]},{"contextId":"u9_35_informal_language_gap_3","answer":"informal language","wrong":["direct object","digital native","reporting verb"]}],"spellingErrors":["informel language","informal langauge","infomal language","informal languge","informal lenguage","informall language"],"masteryPassages":[{"passageId":"u9_35_informal_language_passage_1","contextId":"u9_35_informal_language_gap_1","text":"Words like \"gonna\" and \"stuff\" are common in chats with friends. Examiners expect you to avoid such ____ in a formal report.","answer":"informal language"},{"passageId":"u9_35_informal_language_passage_2","contextId":"u9_35_informal_language_gap_2","text":"A letter to a close cousin can include jokes, contractions and slang. This kind of ____ makes it sound friendly.","answer":"informal language"}],"contextDependentParaphrases":[],"wrongParaphrases":["legal language","technical language","ancient language"],"misleadingDistractors":["words used only in legal documents","the language of scientific reports","a language that is no longer spoken"],"teacherNote":"Noun phrase: relaxed, everyday words and structures (contractions, phrasal verbs, slang) used in personal communication. Key for Paper 2 register: informal language suits a letter to a friend, not a report. Contrast with \"formal style\", also a Unit 9 target. Fixed phrase, so Word Families is not counted."}]'::jsonb,'[]'::jsonb,'["use informal language","avoid informal language","features of informal language"]'::jsonb,'live'),
('vocab_formal_style','formal style','noun','a serious and polite way of writing or speaking, used in official or professional situations','[{"senseId":"formal_style_1","meaning":"a serious and polite way of writing or speaking, used in official or professional situations","acceptedParaphrases":["official tone","serious, polite way of writing"],"masteryContexts":[{"contextId":"u9_36_formal_style_meaning","text":"In a formal style, you would write \"I would be grateful if ...\" instead of \"Can you ...?\".","meaning":"a polite, official way of writing","wrongMeanings":["a relaxed, chatty way of writing","a funny way of writing","a short way of writing"]},{"contextId":"u9_36_formal_style_paraphrase","text":"The speech was in a formal style because the audience included government ministers.","meaning":"a serious way of speaking for official occasions","wrongMeanings":["a relaxed way of speaking for parties","a fast way of speaking for news","a quiet way of speaking for libraries"]}],"situationDistractors":["Two friends sent each other jokes and emojis late at night.","A designer chose a new style of jacket for the winter collection.","An artist sketched a portrait with a pencil.","Two friends chatted about a film over coffee.","A boy sent his sister a message full of emojis.","A fashion designer chose colours for a new dress."],"gapDistractors":[{"contextId":"u9_36_formal_style_gap_1","answer":"formal style","wrong":["direct object","digital native","reporting verb"]},{"contextId":"u9_36_formal_style_gap_2","answer":"formal style","wrong":["direct object","digital native","reporting verb"]},{"contextId":"u9_36_formal_style_gap_3","answer":"formal style","wrong":["direct object","digital native","reporting verb"]}],"spellingErrors":["formel style","formal stile","formall style","formal styel","fromal style","formal stlye"],"masteryPassages":[{"passageId":"u9_36_formal_style_passage_1","contextId":"u9_36_formal_style_gap_1","text":"When you apply for a job, avoid contractions and slang. Use a polite ____ with full sentences.","answer":"formal style"},{"passageId":"u9_36_formal_style_passage_2","contextId":"u9_36_formal_style_gap_2","text":"The article was written for a serious national newspaper. It used a ____, with careful vocabulary and no jokes.","answer":"formal style"}],"contextDependentParaphrases":[],"wrongParaphrases":["chatty tone","fashionable clothing","drawing technique"],"misleadingDistractors":["a relaxed way of chatting with friends","a type of fashionable clothing","a method of drawing pictures"],"teacherNote":"Noun phrase: a serious, polite and impersonal way of writing or speaking (write in a formal style). Features include full forms, precise vocabulary, no slang and polite openings. Key for Paper 2 register. Contrast with \"informal language\", also a Unit 9 target. Fixed phrase, so Word Families is not counted."}]'::jsonb,'[]'::jsonb,'["write in a formal style","a formal style of writing","switch to a formal style"]'::jsonb,'live'),
('vocab_reporting_verb','reporting verb','noun','a verb such as say, tell, suggest or explain that is used to report what someone said or thought','[{"senseId":"reporting_verb_1","meaning":"a verb such as say, tell, suggest or explain that is used to report what someone said or thought","acceptedParaphrases":["verb for reporting speech","verb like say or claim"],"masteryContexts":[{"contextId":"u9_37_reporting_verb_meaning","text":"Choosing a precise reporting verb, such as \"argued\" or \"admitted\", makes a summary more interesting.","meaning":"a word like said or claimed that tells us what someone stated","wrongMeanings":["a word like quickly or slowly that tells us how","a word like big or small that describes a noun","a word like who or what that begins a question"]},{"contextId":"u9_37_reporting_verb_paraphrase","text":"After the reporting verb \"warn\", we usually use an object and \"not to\": She warned us not to go.","meaning":"a word such as said, warned or claimed that introduces what someone stated","wrongMeanings":["a word such as run, jump or swim that shows movement","a word such as and, but or so that joins sentences","a word such as here, there or now that shows place or time"]}],"situationDistractors":["The teacher asked the class to find all the verbs of movement, like \"run\" and \"jump\".","A student underlined every adjective in the story.","A boy wrote a question beginning with \"Do you ...?\".","A student listed adjectives that describe colours.","A teacher explained when to use a full stop.","A girl counted the nouns in a sentence."],"gapDistractors":[{"contextId":"u9_37_reporting_verb_gap_1","answer":"reporting verb","wrong":["digital native","underlying meaning","conference"]},{"contextId":"u9_37_reporting_verb_gap_2","answer":"reporting verb","wrong":["digital native","conference","platform"]},{"contextId":"u9_37_reporting_verb_gap_3","answer":"reporting verb","wrong":["digital native","conference","platform"]}],"spellingErrors":["reportting verb","reporting verbe","reportin verb","reporting vurb","repoting verb","raporting verb"],"masteryPassages":[{"passageId":"u9_37_reporting_verb_passage_1","contextId":"u9_37_reporting_verb_gap_1","text":"Your summary uses the word said eight times. Try a more precise ____ such as admitted, claimed or explained.","answer":"reporting verb"},{"passageId":"u9_37_reporting_verb_passage_2","contextId":"u9_37_reporting_verb_gap_2","text":"Read the sentence: She warned us not to touch the wires. Here, warned is the ____ because it tells us what she said.","answer":"reporting verb"}],"contextDependentParaphrases":[],"wrongParaphrases":["verb of movement","describing word","question word"],"misleadingDistractors":["a verb that describes physical movement","a word used to describe a noun","the main verb in a question"],"teacherNote":"Noun phrase (grammar term): a verb used to report speech or thought (say, tell, explain, suggest, recommend, admit, claim, argue). Different reporting verbs follow different patterns: suggest + -ing / that; recommend + -ing / that; tell + object + to-infinitive. Fixed phrase, so Word Families is not counted."}]'::jsonb,'[]'::jsonb,'["choose a reporting verb","a precise reporting verb","reporting verb patterns"]'::jsonb,'live'),
('vocab_direct_object','direct object','noun','the noun or pronoun that receives the action of a verb, for example "the ball" in "She kicked the ball"','[{"senseId":"direct_object_1","meaning":"the noun or pronoun that receives the action of a verb, for example \"the ball\" in \"She kicked the ball\"","acceptedParaphrases":["person or thing affected by the verb","object that receives the action"],"masteryContexts":[{"contextId":"u9_38_direct_object_meaning","text":"The verb \"tell\" usually needs a direct object: \"She told me the news\".","meaning":"the noun or pronoun receiving the action","wrongMeanings":["the person who does the action","the word that describes how","the time when the action happens"]},{"contextId":"u9_38_direct_object_paraphrase","text":"In \"The teacher praised the students\", the direct object is \"the students\".","meaning":"the person or thing affected by the verb","wrongMeanings":["the person who gives praise","the place where the action happens","the reason for the action"]}],"situationDistractors":["A student identified \"the dog\" as the one doing the action in \"The dog barked\".","A teacher pointed out the word \"quickly\" in \"She ran quickly\".","A boy underlined \"yesterday\" in \"We met yesterday\".","A student found the subject of the sentence \"Birds sing\".","A boy underlined the adverb \"slowly\".","A girl circled the time phrase \"last week\"."],"gapDistractors":[{"contextId":"u9_38_direct_object_gap_1","answer":"direct object","wrong":["digital native","conference","platform"]},{"contextId":"u9_38_direct_object_gap_2","answer":"direct object","wrong":["digital native","conference","generation"]},{"contextId":"u9_38_direct_object_gap_3","answer":"direct object","wrong":["digital native","conference","community"]}],"spellingErrors":["direct objekt","derect object","direct obect","direckt object","direct objct","dirrect object"],"masteryPassages":[{"passageId":"u9_38_direct_object_passage_1","contextId":"u9_38_direct_object_gap_1","text":"Look at the sentence: Amir sent a message. The subject is Amir, and the ____ is a message.","answer":"direct object"},{"passageId":"u9_38_direct_object_passage_2","contextId":"u9_38_direct_object_gap_2","text":"Look at the sentence: I gave my sister a book. My sister is the person who receives it, and a book is the ____ of the verb gave.","answer":"direct object"}],"contextDependentParaphrases":[],"wrongParaphrases":["person doing the action","word describing how","time phrase"],"misleadingDistractors":["the person who does the action","the word that describes how an action happens","the time when an action took place"],"teacherNote":"Noun phrase (grammar term): the noun or pronoun that receives the action of a transitive verb. Important for Unit 9 reporting verbs: \"tell\" needs a person as direct object (tell someone), while \"say\" does not (say something to someone); \"recommend\" and \"suggest\" do not take a person as direct object before a to-infinitive (*suggest him to go). Fixed phrase, so Word Families is not counted."}]'::jsonb,'[]'::jsonb,'["take a direct object","need a direct object","the direct object of the verb"]'::jsonb,'live'),
('vocab_clause','clause','noun','a group of words that contains a subject and a verb and forms a sentence or part of a sentence','[{"senseId":"clause_1","meaning":"a group of words that contains a subject and a verb and forms a sentence or part of a sentence","acceptedParaphrases":["part of a sentence with a verb","subject-and-verb unit"],"masteryContexts":[{"contextId":"u9_39_clause_meaning","text":"After \"suggest\", you can use a clause beginning with \"that\": \"I suggest that you leave early\".","meaning":"a group of words with its own subject and verb","wrongMeanings":["a single word that describes a noun","a punctuation mark between sentences","a paragraph at the end of an essay"]},{"contextId":"u9_39_clause_paraphrase","text":"Starting a clause with \"although\" helps you show contrast in your writing.","meaning":"a part of a sentence containing a verb","wrongMeanings":["a single word showing time","a full paragraph of writing","a title at the top of a page"]}],"situationDistractors":["A student circled every adjective that described the main character.","A teacher added a missing comma to a student’s sentence.","A girl wrote the final paragraph of her essay.","A student added an exclamation mark to the end of a sentence.","A boy circled a single adjective in the text.","A girl wrote the title of her essay."],"gapDistractors":[{"contextId":"u9_39_clause_gap_1","answer":"clause","wrong":["platform","conference","audience"]},{"contextId":"u9_39_clause_gap_2","answer":"clause","wrong":["platform","conference","audience"]},{"contextId":"u9_39_clause_gap_3","answer":"clause","wrong":["platform","conference","audience"]}],"spellingErrors":["clouse","clawse","claus","clauce","cluase","clausse"],"masteryPassages":[{"passageId":"u9_39_clause_passage_1","contextId":"u9_39_clause_gap_1","text":"Look at this sentence: I stayed at home because it was raining. The words because it was raining form a ____ with its own subject and verb.","answer":"clause"},{"passageId":"u9_39_clause_passage_2","contextId":"u9_39_clause_gap_2","text":"Our neighbour, who lives next door, is a doctor. The words who lives next door form a relative ____ that gives extra information.","answer":"clause"}],"contextDependentParaphrases":[],"wrongParaphrases":["single describing word","punctuation mark","final paragraph"],"misleadingDistractors":["a single word that describes a noun","a mark such as a comma or full stop","a paragraph at the end of an essay"],"teacherNote":"Noun (grammar term, countable): a group of words with a subject and a verb (a main clause, a relative clause, a that-clause). Unit 9 links it to reporting verbs: suggest that + clause, recommend that + clause. Boundary: a phrase has no subject-verb pair; a clause does. A legal \"clause\" in a contract is a different sense, not taught. Word Families is not counted."}]'::jsonb,'[]'::jsonb,'["a main clause","a relative clause","a that-clause"]'::jsonb,'live'),
('vocab_suggest','suggest','verb','to put forward an idea or plan for other people to think about','[{"senseId":"suggest_1","meaning":"to put forward an idea or plan for other people to think about","acceptedParaphrases":["propose","put forward an idea"],"masteryContexts":[{"contextId":"u9_40_suggest_meaning","text":"Our teacher likes to suggest that we practise our presentations in front of a mirror.","meaning":"to put forward an idea for someone to consider","wrongMeanings":["to order someone strictly","to refuse to allow something","to complain about something"]},{"contextId":"u9_40_suggest_paraphrase","text":"When the shop was full, Leo said, \"I suggest we try the café across the road.\"","meaning":"to propose a plan","wrongMeanings":["to demand something angrily","to reject a plan","to report a problem"]}],"situationDistractors":["The manager ordered the staff to finish the report by five o’clock.","A boy refused to talk about the plan at all.","A girl agreed with every point her friend made.","The manager ordered everyone to stay late.","A boy refused to discuss where to go on holiday.","A girl agreed with every word her friend said."],"gapDistractors":[{"contextId":"u9_40_suggest_gap_1","answer":"suggest","wrong":["survive","ban","launch"]},{"contextId":"u9_40_suggest_gap_2","answer":"suggest","wrong":["survive","ban","differentiate"]},{"contextId":"u9_40_suggest_gap_3","answer":"suggest","wrong":["survive","ban","launch"]}],"spellingErrors":["sugest","suggets","suggesst","sujest","sugguest","suggist"],"masteryPassages":[{"passageId":"u9_40_suggest_passage_1","contextId":"u9_40_suggest_gap_1","text":"We could not decide where to eat. Tom had an idea, so he said that he would ____ trying the new noodle bar near the station.","answer":"suggest"},{"passageId":"u9_40_suggest_passage_2","contextId":"u9_40_suggest_gap_2","text":"You want to improve your vocabulary quickly. In that case, I ____ that you read a short article every day.","answer":"suggest"}],"contextDependentParaphrases":[],"wrongParaphrases":["order","refuse","agree"],"misleadingDistractors":["to order someone to do something","to refuse to discuss a plan","to agree with everything someone says"],"teacherNote":"Reporting verb: to put forward an idea or plan (suggest + -ing; suggest that + clause; suggest something to someone). Common error: *suggest someone to do. A second meaning, \"to show that something is probably true\" (the evidence suggests ...), is also useful. The noun suggestion is taught in the Word Family pathway."}]'::jsonb,'[]'::jsonb,'["suggest doing something","suggest that","suggest an idea"]'::jsonb,'live')
